    if (!expr || !set_rtrn)
        return false;

    switch (expr->type) {
        case EXPR_BOOL: {
            if (expr->value.bool_val == NULL)
                return false;
            *set_rtrn = expr->value.bool_val;
            return true;
        }

        case EXPR_IDENT: {
            if (strcmp(expr->value.ident, "true") == 0) {
                *set_rtrn = true;
